// LikeDeleteOne builds the delete of one `likes` row. Start one with
// `Graph.likes().delete_one(node)` or `delete_one_id(id)`.
pub struct LikeDeleteOne {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete_one starts the delete of the row of `node`.
pub fn (q LikeQuery) delete_one(node LikeNode) LikeDeleteOne {
	return q.delete_one_id(node.like.id)
}

// delete_one_id starts the delete of the row with the key `id`.
pub fn (q LikeQuery) delete_one_id(id int) LikeDeleteOne {
	return LikeDeleteOne{
		graph: q.graph
		data:  vgraph.MutationData{
			op:      .delete_one
			table:   'likes'
			row_key: id.str()
		}
	}
}

// exec deletes the row, with its join table rows, in one transaction, or
// returns a `NotFoundError`.
pub fn (b LikeDeleteOne) exec() ! {
	if !b.graph.client.delete_one(b.data)! {
		return NotFoundError{
			table: 'likes'
		}
	}
}

// LikeDelete builds the delete of the `likes` rows that match its conditions.
// Start one with `Graph.likes().delete()`.
pub struct LikeDelete {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete starts the delete of the rows that match the query's conditions; its
// order, limit and offset don't apply.
pub fn (q LikeQuery) delete() LikeDelete {
	return LikeDelete{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .delete
			table: 'likes'
			conds: q.query.conds.clone()
		}
	}
}

// where keeps the rows that match every one of `conds`.
pub fn (b LikeDelete) where(conds ...load.Cond) LikeDelete {
	return LikeDelete{
		...b
		data: b.data.with_conds(conds)
	}
}

