// likes_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) likes_by_keys(keys []string) ![]LikeNode {
	// as stored: no privacy rule or interceptor hides a row just written
	rows := Graph{
		client: g.client.bypass()
	}.likes().where(load.in_keys('id', keys, .int)).all()!
	mut by_key := map[string]LikeNode{}
	for row in rows {
		by_key[row.like.id.str()] = row
	}
	mut found := []LikeNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'likes'
			}
		}
	}
	return found
}

// CreateLikeInput is what a create of a `likes` row sets, as the GraphQL input
// `CreateLikeInput` gives it: `none` and empty lists leave things as
// they are.
pub struct CreateLikeInput {
pub mut:
	user_id   ?int
	gadget_id ?i64
	liked_at  ?time.Time
}

// set_input sets what `input` gives: clears first, then values, then edges.
pub fn (b LikeCreate) set_input(input CreateLikeInput) LikeCreate {
	mut next := b
	if v := input.user_id {
		next = next.set_user_id(v)
	}
	if v := input.gadget_id {
		next = next.set_gadget_id(v)
	}
	if v := input.liked_at {
		next = next.set_liked_at(v)
	}
	return next
}

